#include <vector>
#include <stdexcept>
#include <unordered_set>

static void validate_graph(int node_count, const std::vector<std::vector<int>>& edges) {
  if (node_count <= 0) throw std::invalid_argument("节点数必须是正整数");
  for (const auto& edge : edges) {
    if (edge.size() != 2) throw std::invalid_argument("每条边必须是长度为 2 的容器");
    int left = edge[0], right = edge[1];
    if (left < 0 || left >= node_count || right < 0 || right >= node_count) {
      throw std::invalid_argument("边的节点必须在合法范围内 [0, " + std::to_string(node_count - 1) + "]");
    }
  }
  // 可选：检查是否有重复边
  std::unordered_set<std::pair<int, int>> seen_edges;
  for (const auto& edge : edges) {
    int left = edge[0], right = edge[1];
    // 避免重复边，比如 (1,2) 和 (2,1) 被视为不同的边
    if (seen_edges.find({left, right}) != seen_edges.end()) {
      throw std::invalid_argument("重复边检测失败");
    }
    seen_edges.insert({left, right});
  }
}
```

